import{_ as a,b as o,c as t,f as e}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/16.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/16.md"}'),l={name:"articles/artificial-intelligence/books/AI-modern-approach-homework/16.md"};function P(n,r,i,c,d,s){return o(),t("div",null,[...r[0]||(r[0]=[e("p",null,"基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 16 章，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来。",-1),e("p",null,"基础题（概念与简单计算） 题目1 假设你参加一个抽奖：有 40% 的概率赢得 500 元，60% 的概率赢得 100 元。你的效用函数为 U(x)=√x（x 为金额）。 (a) 计算该抽奖的期望货币价值。 (b) 计算你的期望效用。 (c) 求与你期望效用相等的确定等价金额（即满足 U(CE)=EU 的 CE）。 (d) 你是风险厌恶、中性还是寻求？为什么？ 题目2 决策网络：我们有三个布尔变量 A,B,C，决策节点 D（两个选择：d1, d2），效用节点 U 依赖于 C 和 D，已知： P(A)=0.6 P(B∣A)=0.8,P(B∣¬A)=0.3 P(C∣A,B)=0.9（若 A=1,B=1），否则 P(C=1∣A,B)=0.2 效用表：U(C=1,D=d1)=100,U(C=0,D=d1)=0,U(C=1,D=d2)=50,U(C=0,D=d2)=40 绘制影响图（节点与边），并计算选择 d1 和 d2 的期望效用，判断最优动作。 题目3 简述完全信息价值（VPI）的定义。为什么 VPI 不会为负？举一个例子说明 VPI 等于零的情况。",-1),e("p",null,"进阶题（分析、建模与求解） 题目4 多属性效用：你想购买一辆汽车，考虑两个属性：价格（P）和油耗（F）。价格分为低中高三档（L, M, H），油耗分为好、中、差（G, M, B）。你的效用函数为 U(P,F)=w_P u_P (P)+w_F u_F (F)，其中 w_P=0.6,w_F=0.4。 单属性效用值： u_P (L)=1,u_P (M)=0.5,u_P (H)=0 u_F (G)=1,u_F (M)=0.6,u_F (B)=0 现有两辆车：车1（价格M，油耗G），车2（价格L，油耗M）。计算各自的总效用，并推荐购买哪一辆。 题目5 价值信息：一个决策问题：你有两个动作 A1 和 A2，结果依赖于一个布尔变量 S。已知先验 P(S=1)=0.4。效用表： 若 S=1：U(A1)=100, U(A2)=0 若 S=0：U(A1)=0, U(A2)=50 (1) 不获取信息时，计算每个动作的期望效用，并选择最优。 (2) 假设你可以花10元进行一次检测，检测结果 T 为 1 或 0。已知检测的准确率：P(T=1∣S=1)=0.9,P(T=1∣S=0)=0.2。求完全信息价值（VPI）以及该检测的信息价值（VPI）。你应该做检测吗？ 题目6 影响图评估：给定一个影响图，决策节点 D，机遇节点 X, Y, Z，效用节点 U 依赖于 X 和 Z。转移概率：P(X),P(Y∣X),P(Z∣X,Y)。写出在给定信息（例如已知观测到 Y=y）时，计算选择 d 的期望效用的表达式（用求和或积分）。解释如何利用贝叶斯网络推理计算后验。",-1),e("hr",null,null,-1),e("p",null,"综合题（设计、比较、开放） 题目7 医疗决策建模：医生需要决定是否给患者进行一个手术（Surgery 或 NoSurgery）。患者可能有某种疾病 D（布尔），已知先验 P(D)=0.1。手术可以治愈疾病（若患者有病），但亦有风险。效用考虑健康状态和费用。设健康状态 H 有三个等级：好、一般、差。最终效用依赖于 H 和总费用。 已知： 若无手术且无病：H=好，费用0。 若无手术且有病：H=差，费用0。 若有手术且无病：H=一般（手术副作用），费用5000。 若有手术且有病：有0.9概率治愈（H=好，费用5000），0.1概率失败（H=差，费用5000）。 (1) 定义变量，画出决策网络（影响图）。 (2) 列出所有需要的概率和效用值，并计算手术与不手术的期望效用，假设效用是金钱的线性函数（即效用就是 -费用 + 健康价值，健康价值：好=10000，一般=2000，差=0）。 (3) 如果医生可以通过一个诊断测试（假阳性率0.1，假阴性率0.2）来获得关于 D 的信息，测试费用1000。求检测的信息价值，并判断是否值得做测试。 题目8 效用函数校准：你是一个风险中性的投资者，考虑两个投资方案：方案A：50%概率收益2000，50%概率损失500；方案B：确定收益700。 (1) 请计算期望收益，并选择最优方案。若你是风险厌恶者，会如何改变选择？ (2) 使用指数效用函数 U(x)=1-e^(-x/R)，其中 R 是风险承受系数。对于 R=2000，计算两个方案的期望效用，并比较。 (3) 如何通过问卷或实验来估计一个决策者的风险厌恶系数 R？请简述方法。 题目9 信息价值非加性示例：已知两个布尔变量 X,Y，决策 D 的效用依赖于 X 和 Y。先验 P(X=1)=0.5,P(Y=1)=0.5，且 X 和 Y 独立。效用表： 若 (X=1,Y=1): U=100 若 (X=1,Y=0): U=0 若 (X=0,Y=1): U=0 若 (X=0,Y=0): U=0 (1) 计算单独知道 X 的信息价值和单独知道 Y 的信息价值。 (2) 计算同时知道 X 和 Y 的信息价值。 (3) 验证 VPI(X,Y) ≤ VPI(X)+VPI(Y) 是否成立？解释为什么信息价值是次可加的（即合起来可能小于和）。 题目10（开放设计） 智能投顾系统：设计一个简化的投资决策智能体，根据用户的年龄、风险偏好、市场预期（上涨/下跌概率）来推荐资产配置（股票、债券、现金）。 (1) 定义状态变量（如年龄组、风险偏好类型、市场预期）。 (2) 定义动作（配置比例）。 (3) 定义效用函数（考虑收益、风险、用户退休目标）。 (4) 利用决策网络或决策树，说明如何计算期望效用，并选出最优配置。 (5) 讨论如何通过用户交互（问卷）来获取效用函数参数。",-1)])])}const u=a(l,[["render",P]]);export{p as __pageData,u as default};
